import{_ as a,C as c,o as t,c as i,a2 as r,b as l,w as o,a as C,E as s,a3 as n}from"./chunks/framework.BaXgE4DV.js";const m=JSON.parse('{"title":"Circle","description":"","frontmatter":{},"headers":[],"relativePath":"features/circles.md","filePath":"features/circles.md","lastUpdated":1791545689000}'),E={name:"features/circles.md"};function u(B,e,h,A,p,b){const d=c("Mermaid");return t(),i("div",null,[e[1]||(e[1]=r('<h1 id="circle" tabindex="-1">Circle <a class="header-anchor" href="#circle" aria-label="Permalink to &quot;Circle&quot;">​</a></h1><p>Circle은 감사를 함께 나누는 소규모 비공개 그룹입니다. 공개 목록이나 검색은 없고 초대 코드로만 참여합니다. 사용자는 여러 Circle에 참여할 수 있습니다. 글은 기본이 &quot;나만 보기&quot;이고, 글을 쓸 때 &quot;Circle에 공유&quot;와 Circle을 직접 고른 경우에만 그 Circle에 보입니다. → <a href="/grato-docs/features/gratitudes#visibility">공개 범위</a></p><p>멤버십 변경(생성·참여·탈퇴·내보내기·삭제·초대 코드)은 <strong>모두 callable 함수</strong>가 처리합니다. 클라이언트는 그룹의 이름·설명·사진만 직접 고칠 수 있고, 그것도 관리자만 가능합니다. → <a href="/grato-docs/decisions#adr-3">결정 기록 #3</a></p><h2 id="한도" tabindex="-1">한도 <a class="header-anchor" href="#한도" aria-label="Permalink to &quot;한도&quot;">​</a></h2><table tabindex="0"><thead><tr><th>항목</th><th>값</th><th>확인 위치</th></tr></thead><tbody><tr><td>사용자당 참여 Circle</td><td>20개</td><td><code>createCircle</code>, <code>joinCircle</code></td></tr><tr><td>Circle당 멤버</td><td>50명</td><td><code>joinCircle</code></td></tr><tr><td>초대 코드 유효 기간</td><td>발급 후 30일</td><td><code>joinCircle</code></td></tr><tr><td>초대 코드 사용 횟수</td><td>50회</td><td><code>joinCircle</code></td></tr><tr><td>Circle 이름</td><td>1~30자</td><td>함수, 규칙(관리자 수정)</td></tr><tr><td>Circle 설명</td><td>100자 이하</td><td>함수, 규칙(관리자 수정)</td></tr><tr><td>Circle 사진</td><td>이미지, 5MB 미만, 관리자만</td><td>Storage 규칙</td></tr></tbody></table><p>Circle 수를 셀 때는 <code>users.groupIds</code>를 그대로 믿지 않고, 함수가 각 그룹 문서를 읽어 <strong>실제로 멤버인 Circle만</strong> 셉니다. 삭제된 Circle이나 내보내진 Circle의 ID가 남아 있어도 한도에 걸리지 않고, 그 자리에서 정리됩니다.</p><h2 id="역할" tabindex="-1">역할 <a class="header-anchor" href="#역할" aria-label="Permalink to &quot;역할&quot;">​</a></h2><table tabindex="0"><thead><tr><th>역할</th><th>할 수 있는 일</th></tr></thead><tbody><tr><td>관리자 (<code>adminId</code>, 생성자)</td><td>이름·설명·사진 수정, 초대 코드 재발급, 멤버 내보내기·다시 허용, Circle 삭제. 탈퇴는 불가</td></tr><tr><td>멤버</td><td>글 읽기·쓰기, 리액션, 댓글, 탈퇴</td></tr></tbody></table><p>관리자 위임 기능은 아직 없습니다. 다만 관리자가 <a href="/grato-docs/features/account#deletion-scope">계정을 삭제</a>하면 가장 오래 함께한 멤버(<code>memberIds</code>의 참여 순서)가 자동으로 관리자가 되고, 혼자였다면 Circle이 삭제됩니다.</p><p>멤버는 Circle 설정의 멤버 목록에서 다른 멤버를 신고·차단할 수 있고, 관리자가 아닌 멤버는 &quot;Circle 신고하기&quot;로 Circle 자체를 신고할 수 있습니다. 차단은 내 화면만 바꾸고 멤버십은 그대로입니다. → <a href="/grato-docs/features/safety">신고·차단</a></p><h2 id="생성" tabindex="-1">생성 <a class="header-anchor" href="#생성" aria-label="Permalink to &quot;생성&quot;">​</a></h2><p><code>createCircle({name, description})</code> → <code>{groupId, inviteCode}</code></p><p>한 트랜잭션에서 그룹 문서(<code>memberIds: [나]</code>, <code>adminId: 나</code>, <code>plan: &quot;free&quot;</code>), 초대 코드 문서, 내 <code>groupIds</code>를 함께 만듭니다. 초대 코드가 이미 쓰이고 있으면 최대 5번까지 다시 뽑습니다. 이름·설명에 욕설·혐오 표현이 있으면 &quot;Circle 이름이나 설명에 쓸 수 없는 표현이 있어요&quot;로 거절합니다.</p><h2 id="초대-코드" tabindex="-1">초대 코드 <a class="header-anchor" href="#초대-코드" aria-label="Permalink to &quot;초대 코드&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>새 코드</th><th>예전 코드</th></tr></thead><tbody><tr><td>형식</td><td>8자리, <code>ABCDEFGHJKLMNPQRSTUVWXYZ23456789</code> (헷갈리는 <code>0 O 1 I</code> 제외)</td><td>대부분 6자리 영숫자</td></tr><tr><td>생성</td><td><code>crypto.randomInt</code> (암호학적 난수, 편향 없음)</td><td>-</td></tr><tr><td>만료·사용 횟수</td><td>30일, 50회</td><td>필드가 없으면 무제한</td></tr></tbody></table><ul><li>입력은 앞뒤 공백 제거 후 대문자로 바꿉니다(<code>normalizeInviteCode</code>). 영숫자 1~16자가 아니면 &quot;초대 코드를 찾을 수 없어요&quot;입니다.</li><li>초대 링크는 <code>https://grato.today/invite/{코드}</code> 형식입니다. 링크 미리보기(Circle 이름, 인원)는 <code>shareRenderer</code>가 만듭니다.</li><li>클라이언트는 아는 코드 하나만 조회할 수 있고 코드 목록은 볼 수 없습니다.</li></ul><h2 id="join" tabindex="-1">참여 <a class="header-anchor" href="#join" aria-label="Permalink to &quot;참여 {#join}&quot;">​</a></h2>',17)),(t(),l(n,null,{default:o(()=>[s(d,{id:"mermaid-230",class:"mermaid",graph:"sequenceDiagram%0A%20%20participant%20U%20as%20%EC%82%AC%EC%9A%A9%EC%9E%90%0A%20%20participant%20C%20as%20%ED%81%B4%EB%9D%BC%EC%9D%B4%EC%96%B8%ED%8A%B8%0A%20%20participant%20J%20as%20joinCircle%0A%20%20participant%20F%20as%20Firestore%0A%20%20U-%3E%3EC%3A%20%EC%B4%88%EB%8C%80%20%EB%A7%81%ED%81%AC%20%EC%97%B4%EA%B8%B0%20%EB%98%90%EB%8A%94%20%EC%BD%94%EB%93%9C%20%EC%9E%85%EB%A0%A5%0A%20%20Note%20over%20C%3A%20%EB%B9%84%EB%A1%9C%EA%B7%B8%EC%9D%B8%EC%9D%B4%EB%A9%B4%20pendingInviteCode%20%EC%A0%80%EC%9E%A5%20%ED%9B%84%20%EB%A1%9C%EA%B7%B8%EC%9D%B8%0A%20%20C-%3E%3EC%3A%20profileReady%20%EB%8C%80%EA%B8%B0%20(users%20%EB%AC%B8%EC%84%9C%20%EB%A8%BC%EC%A0%80%20%EC%83%9D%EC%84%B1)%0A%20%20C-%3E%3EJ%3A%20joinCircle(%7Bcode%7D)%0A%20%20J-%3E%3EF%3A%20%ED%8A%B8%EB%9E%9C%EC%9E%AD%EC%85%98%20%EC%8B%9C%EC%9E%91%20%C2%B7%20inviteCodes%2F%7Bcode%7D%20%EC%9D%BD%EA%B8%B0%0A%20%20J-%3E%3EF%3A%20groups%2F%7BgroupId%7D%20%C2%B7%20users%2F%7Buid%7D%20%EC%9D%BD%EA%B8%B0%0A%20%20alt%20%EC%9D%B4%EB%AF%B8%20%EB%A9%A4%EB%B2%84%0A%20%20%20%20J-%3E%3EF%3A%20%ED%95%84%EC%9A%94%ED%95%98%EB%A9%B4%20groupIds%20%EB%B3%B5%EA%B5%AC%0A%20%20%20%20J--%3E%3EC%3A%20alreadyMember%20%3D%20true%0A%20%20else%20%EC%83%88%20%EC%B0%B8%EC%97%AC%0A%20%20%20%20Note%20over%20J%3A%20%EC%B0%A8%EB%8B%A8%20%EB%AA%A9%EB%A1%9D%20%C2%B7%20%EB%A7%8C%EB%A3%8C%20%C2%B7%20%EC%82%AC%EC%9A%A9%20%ED%9A%9F%EC%88%98%20%C2%B7%20%EC%A0%95%EC%9B%90%20%C2%B7%20Circle%20%EC%88%98%20%ED%99%95%EC%9D%B8%0A%20%20%20%20J-%3E%3EF%3A%20memberIds%20%2B%3D%20uid%0A%20%20%20%20J-%3E%3EF%3A%20groupIds%20%EA%B0%B1%EC%8B%A0%20(%EC%98%A4%EB%9E%98%EB%90%9C%20ID%20%EC%A0%95%EB%A6%AC)%0A%20%20%20%20J-%3E%3EF%3A%20useCount%20%2B%3D%201%0A%20%20%20%20J--%3E%3EC%3A%20alreadyMember%20%3D%20false%0A%20%20end%0A%20%20C-%3E%3EC%3A%20%ED%95%B4%EB%8B%B9%20Circle%EC%9D%84%20%EC%84%A0%ED%83%9D%ED%95%98%EA%B3%A0%20%ED%99%88%EC%9C%BC%EB%A1%9C%20%EC%9D%B4%EB%8F%99%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[C(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<ul><li>이미 멤버면 오류가 아니라 <code>alreadyMember: true</code>이고 사용 횟수를 차감하지 않습니다.</li><li>검사 순서: 코드 존재 → Circle 존재 → 이미 멤버 → <strong>내보낸 사용자</strong> → 만료 → 사용 횟수 → 정원 → 내 Circle 수.</li><li>신규 사용자는 클라이언트가 <code>users/{uid}</code>를 먼저 만들도록 <code>profileReady</code>를 기다린 뒤 참여합니다.</li><li>인앱 브라우저(카카오톡 등)에서는 Google 로그인이 막힙니다. <strong>카카오톡·LINE</strong>에서 초대 링크를 열면 초대 페이지가 한 번 자동으로 휴대폰 브라우저에 넘깁니다(카카오톡 <code>kakaotalk://web/openExternal</code>, LINE <code>openExternalBrowser=1</code>). 앱이 설치된 휴대폰이면 이때 Universal Link·App Link로 <strong>앱의 초대 화면</strong>이 열립니다. 넘기지 못하면(다른 인앱 브라우저, 세션당 한 번 시도 뒤) 브라우저 열기·링크 복사 안내를 보여 줍니다. <code>src/lib/inAppBrowser.js</code>의 <code>externalBrowserUrl</code>.</li><li>초대 메시지(<code>inviteMessage</code>)에는 링크와 함께 초대 코드가 들어 있어, 앱에서 &quot;Circle 참여하기&quot;에 코드를 넣어도 됩니다.</li><li>Circle을 만들면 바로 &quot;초대하기&quot; 카드(공유 시트, 카카오톡 포함)가 나옵니다. 혼자인 Circle은 쓰이지 않아서입니다.</li></ul><p>오류 메시지 전체는 <a href="/grato-docs/architecture/cloud-functions#circle-errors">Cloud Functions</a>에 있습니다.</p><h2 id="탈퇴" tabindex="-1">탈퇴 <a class="header-anchor" href="#탈퇴" aria-label="Permalink to &quot;탈퇴&quot;">​</a></h2><p><code>leaveCircle({groupId})</code> — 내 uid를 <code>memberIds</code>에서, Circle을 내 <code>groupIds</code>에서 뺍니다. 관리자는 탈퇴할 수 없습니다(먼저 Circle을 삭제해야 함).</p><p>Circle이 이미 없거나 내가 멤버가 아니면 <code>groupIds</code>만 정리하고 성공합니다. 클라이언트는 이것을 이용해 삭제가 확인된 Circle의 오래된 ID를 서버에서도 지웁니다.</p><h2 id="멤버-내보내기와-다시-허용" tabindex="-1">멤버 내보내기와 다시 허용 <a class="header-anchor" href="#멤버-내보내기와-다시-허용" aria-label="Permalink to &quot;멤버 내보내기와 다시 허용&quot;">​</a></h2><table tabindex="0"><thead><tr><th>함수</th><th>동작</th></tr></thead><tbody><tr><td><code>removeCircleMember({groupId, memberId})</code></td><td><code>memberIds</code>에서 제거, <code>removedIds</code>에 추가, 그 사람의 <code>groupIds</code>에서 제거</td></tr><tr><td><code>unbanCircleMember({groupId, memberId})</code></td><td><code>removedIds</code>에서 제거</td></tr></tbody></table><ul><li>내보낸 사람은 이미 알고 있는 초대 코드로 <strong>다시 들어올 수 없습니다.</strong> &quot;이 Circle에서 내보내져 다시 참여할 수 없어요. Circle 관리자에게 문의해주세요&quot; 오류를 받습니다.</li><li>관리자는 Circle 설정의 &quot;내보낸 멤버&quot; 목록에서 <strong>다시 허용</strong>할 수 있습니다. 다시 허용해도 자동으로 멤버가 되지는 않고, 초대 코드로 다시 참여해야 합니다.</li><li>초대 코드를 바꾸지 않아도 차단이 유지되므로, 한 사람을 내보내려고 모든 멤버에게 새 코드를 나눠 줄 필요가 없습니다.</li><li>내보내진 사람이 그 Circle에 쓴 글은 작성자 본인에게 계속 보입니다. 그 사람은 더 이상 Circle 피드를 읽거나 새 글을 올릴 수 없습니다.</li></ul><h2 id="circle-삭제" tabindex="-1">Circle 삭제 <a class="header-anchor" href="#circle-삭제" aria-label="Permalink to &quot;Circle 삭제&quot;">​</a></h2><p><code>deleteCircle({groupId})</code> — 관리자만 가능합니다.</p><ol><li>모든 멤버의 <code>users.groupIds</code>에서 이 Circle 제거 (없는 사용자 문서는 건너뜀)</li><li>이 Circle을 가리키는 초대 코드 전부 삭제</li><li>그룹 문서 삭제 (<strong>마지막</strong>)</li><li>Circle 사진(<code>circlePhotos/{groupId}/</code>) 삭제 (실패해도 로그만)</li></ol><p>운영자가 신고된 Circle을 지울 때(<code>moderate</code>)도 같은 처리를 씁니다. 500개 단위 배치로 나눠 커밋합니다. 그룹 문서를 마지막에 지우므로 중간에 실패해도 다시 호출하면 이어서 정리됩니다.</p><p><strong>감사 글은 지우지 않습니다.</strong> 그룹 문서가 사라지면 다른 멤버는 그 글을 읽을 수 없게 되지만, 작성자는 자기 글을 개인 기록으로 계속 봅니다. → <a href="/grato-docs/decisions#adr-4">결정 기록 #4</a></p><h2 id="초대-코드-재발급" tabindex="-1">초대 코드 재발급 <a class="header-anchor" href="#초대-코드-재발급" aria-label="Permalink to &quot;초대 코드 재발급&quot;">​</a></h2><p><code>regenerateInviteCode({groupId})</code> → <code>{inviteCode}</code> — 관리자만. 기존 코드 문서를 <strong>모두</strong> 지우고 새 코드를 만든 뒤 <code>groups.inviteCode</code>를 바꿉니다. 한 트랜잭션이라 중간 상태가 없습니다. 기존 링크·코드는 즉시 쓸 수 없게 됩니다.</p><h2 id="circle-정보-수정" tabindex="-1">Circle 정보 수정 <a class="header-anchor" href="#circle-정보-수정" aria-label="Permalink to &quot;Circle 정보 수정&quot;">​</a></h2><p>관리자는 Firestore에 직접 <code>name</code>(1~30자), <code>description</code>(100자 이하), <code>photoURL</code>만 수정할 수 있습니다. 이름·설명을 바꾸면 서버가 내용 필터로 검사해, 걸리면 그대로 두고 운영자에게 알립니다(<code>onCircleNameWritten</code>). 사진은 Storage <code>circlePhotos/{groupId}/</code>에 올리며, Storage 규칙이 Firestore의 <code>adminId</code>를 교차 확인합니다. → <a href="/grato-docs/architecture/security-rules#storage">보안 규칙</a></p><h2 id="피드" tabindex="-1">피드 <a class="header-anchor" href="#피드" aria-label="Permalink to &quot;피드&quot;">​</a></h2><ul><li>Circle별로 최신 20개를 실시간 구독하고, &quot;더 보기&quot;는 커서(<code>startAfter</code>) 기반으로 20개씩 읽습니다.</li><li>여러 Circle을 한 번에 합친 피드는 지원하지 않습니다. 규칙의 교차 읽기 한도 때문에 Circle마다 쿼리를 따로 보냅니다. → <a href="/grato-docs/architecture/security-rules#get-list">보안 규칙</a></li><li>홈의 &quot;오늘의 Circle 활동&quot;은 최대 10개 Circle에 대해 오늘(KST) 글 수와 리액션 수를 병렬로 집계합니다.</li><li>구독 중 권한이 사라지면(내보내짐 등) 빈 피드로 처리해 로딩이 끝나지 않는 일을 막습니다.</li></ul>',19))])}const q=a(E,[["render",u]]);export{m as __pageData,q as default};
